const items = $input.all();
const results = [];

for (const item of items) {
  let output = item.json.output || item.json.text || '';

  // CORREÇÃO 1: Se a resposta contém JSON de tool call exposto, limpa
  if (output.includes('"recipient_name"') || 
      output.includes('"functions.') ||
      output.includes('"Prompt__User_Message_"') ||
      (output.startsWith('{') && output.includes('"parameters"'))) {
    output = 'Hmm, tive um probleminha técnico 😅 Pode repetir o que precisa? Posso anotar tarefas, remarcar, marcar como feita...';
  }

  // CORREÇÃO 2: Remove = do início da resposta (se sobrou do bug de escape)
  if (output.startsWith('=')) {
    output = output.substring(1).trim();
  }

  // CORREÇÃO 3: Detecta mensagens intermediárias / gerúndio / "aguarde"
  const intermediaryPatterns = [
    /está sendo processad/i,
    /aguarde a confirmação/i,
    /aguarde as próximas/i,
    /próximas instruções/i,
    /sendo processad/i,
    /será processad/i,
    /continuo criando/i,
    /estou salvando/i,
    /estou processando/i,
    /estou encaminhando/i,
    /vou encaminhar/i,
    /vou classificar/i,
    /vou analisar/i,
    /vou verificar/i,
    /vou processar/i,
  ];

  if (intermediaryPatterns.some(p => p.test(output))) {
    output = 'Hmm, tive um probleminha técnico 😅 Pode repetir o que precisa? Posso anotar tarefas, remarcar, marcar como feita...';
  }

  // CORREÇÃO 4: Detecta vazamento de nomes internos
  // NOTA: recurrence_id foi REMOVIDO desta lista — a resposta do subagente_recorrencia
  // pode conter esse termo legitimamente e não deve ser filtrada.
  const internalLeakPatterns = [
    /subagente_/i,
    /agente_tarefas/i,
    /agente_busca/i,
    /agente_config/i,
    /vou delegar/i,
    /re-delegar/i,
    /delegar novamente/i,
    /delegando para/i,
    /tool_call/i,
    /task_search/i,
    /task_create/i,
    /task_delete/i,
    /task_update/i,
    /task_list/i,
    /task_period/i,
    /task_generate/i,
    /user_phone/i,
    /fromAI\(/i,
    /Prompt__User_Message_/i,
    /orquestrador/i,
    /decisão do usuário pós/i,
    /FLUXO DE CRIAÇÃO/i,
    /FLUXO EM ANDAMENTO/i,
    /MÚLTIPLAS INTENÇÕES/i,
    /TASK_IDS JÁ CONHECIDOS/i,
    /tool_uses/i,
    /recipient_name/i,
    /classificar a intenção/i,
    /classificação de intenção/i,
  ];

  if (internalLeakPatterns.some(p => p.test(output))) {
    output = 'Hmm, tive um probleminha técnico 😅 Pode repetir o que precisa? Posso anotar tarefas, remarcar, marcar como feita...';
  }

  // CORREÇÃO 5: Trunca mensagens longas para o limite do WhatsApp (~4000 chars)
  if (output.length > 4000) {
    const truncated = output.substring(0, 3900);
    const lastNewline = truncated.lastIndexOf('\n');
    output = (lastNewline > 3000 ? truncated.substring(0, lastNewline) : truncated) 
      + '\n\n_(mensagem truncada — envie "continua" para ver o restante)_';
  }

  results.push({ json: { Resposta: output } });
}

return results;

const items = $input.all();

const context = items.map(item => {
  let message = item.json.message;

  if (typeof message === "string") {
    try {
      // Remove problematic control characters
      const cleaned = message
        .replace(/[\u0000-\u001F]+/g, " ")
        .trim();

      message = JSON.parse(cleaned);
    } catch (err) {
      message = {
        type: "unknown",
        content: item.json.message
      };
    }
  }

  return {
    json: {
      type: message?.type,
      content: message?.content,
      created_at: item.json.created_at
    }
  };
});

return [
  {
    json: {
      chat_context: context
    }
  }
];;


return {"chat_context": context };
